export function WrenExtensionsPanel(props:{workspaceId:string;conversationId?:string;installationId?:string;catalogSlug?:string;app?:string;openRequest?:number;onUse?:(prompt:string)=>void;githubResult?:string}){return <ExtensionsScope key={`${props.workspaceId}:${props.conversationId??""}:${props.installationId??""}:${props.catalogSlug??""}:${props.app??""}`} {...props}/>;}
