 {visibleSources.map(entry=>{const existing=installedSource(added,entry);return <AppRow key={entry.slug} icon={<AppTile name={entry.manifest.name} origin={entry.manifest.origin} tools={entry.manifest.tools}/>} name={entry.manifest.name} sub={`${entry.category} · No sign-in`} onOpen={()=>setBrowse({...browse,selected:entry.slug})} trailing={existing?<RowStatus>Added</RowStatus>:target&&writer?<AddButton label={`Add ${entry.manifest.name}`} busy={addBusy===entry.slug} onAdd={()=>void quickAdd(entry)}/>:undefined}/>;})}
 {visibleCustom.map(item=><AppRow key={item.id} icon={<AppTile name={item.manifest.name} origin={item.manifest.origin} tools={item.manifest.tools}/>} name={item.manifest.name} sub={`Workspace · Published by ${publisher(item)}`} onOpen={()=>setPackageID(item.id)} trailing={added.some(value=>value.extensionId===item.id)?<RowStatus>Added</RowStatus>:<AddButton label={`Set up ${item.manifest.name}`} onAdd={()=>setPackageID(item.id)}/>}/>)}
